<?php require_once 'includes/auth.php'; require_admin();$q=trim($_GET['q']??'');$status=trim($_GET['status']??'');$category=trim($_GET['category']??'');$sql='SELECT c.*,u.name,u.email FROM complaints c JOIN users u ON u.id=c.user_id WHERE 1=1';$args=[];if($q){$sql.=' AND (c.description LIKE ? OR c.location LIKE ? OR c.category LIKE ? OR u.name LIKE ?)';$like="%$q%";$args=array_merge($args,[$like,$like,$like,$like]);}if($status){$sql.=' AND c.status=?';$args[]=$status;}if($category){$sql.=' AND c.category=?';$args[]=$category;}$sql.=' ORDER BY c.created_at DESC';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$page_title='Manage Complaints';include 'includes/header.php';?><div class="page-head compact"><div><div class="eyebrow">OPERATIONS</div><h1>Manage complaints</h1><p class="muted">Search, filter and update campus reports.</p></div></div><form class="filters"><div class="search-wrap"><span>⌕</span><input name="q" value="<?=e($q)?>" placeholder="Search complaints, students, locations..."></div><select name="status"><option value="">All statuses</option><?php foreach(['Pending','Assigned','In Progress','Resolved'] as $s):?><option <?= $status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><select name="category"><option value="">All categories</option><?php foreach(['Electrical','Plumbing','Internet','Furniture','Cleaning','Other'] as $s):?><option <?= $category===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn btn-secondary">Filter</button></form><div class="table-card"><div class="data-table"><div class="tr th"><span>Complaint</span><span>Student</span><span>Location</span><span>Status</span><span>Updated</span></div><?php foreach($rows as $c):?><a class="tr" href="complaint.php?id=<?=$c['id']?>"><span><b>#<?=e($c['id'])?></b><small><?=e($c['category'])?> · <?=e(mb_strimwidth($c['description'],0,42,'…'))?></small></span><span><b><?=e($c['name'])?></b><small><?=e($c['email'])?></small></span><span><?=e($c['location'])?></span><span><?=status_badge($c['status'])?></span><span><?=e(date('d M Y',strtotime($c['updated_at'])))?></span></a><?php endforeach;?></div></div><?php if(!$rows):?><div class="empty-state small"><div class="empty-icon">⌕</div><h3>No complaints found</h3><p>Adjust your filters and try again.</p></div><?php endif;?><?php include 'includes/footer.php'; ?>
